Given a sorted array of distinct elements arr[] of size n that is rotated at some unknown point, the task is to find the minimum element in it. Examples: Input: arr[] = [5, 6, 1, 2, 3, 4]Output: 1Explanation: 1 is the minimum element present in the array.Input: arr[] = [3, 1, 2]Output: 1Explanation: 1 is the minimum element present in the array.Input: arr[] = [4, 2, 3]Output: 2Explanation: 2 is the only minimum element in the array.Try It YourselfTable of Content[Naive Approach] Linear Search - O(n) Time and O(1) Space[Expected Approach] Binary Search - O(log n) Time and O(1) Space[Naive Approach] Linear Search - O(n) Time and O(1) SpaceA simple solution is to use linear search to traverse the complete array and find a minimum. 
            C++

    #include <iostream>
#include <vector>
using namespace std;

int findMin(vector<int>& arr) {

    int res = arr[0];

    // Traverse over arr[] to find minimum element
    for (int i = 1; i < arr.size(); i++) 
        res = min(res, arr[i]);

    return res;
}

int main() {
    vector<int> arr = {5, 6, 1, 2, 3, 4};
    int n = arr.size();

    cout << findMin(arr) << endl;
    return 0;
}


